// The tables of one truncation level; a table with no modes for an untabulated level.
inline c_ObliquitySeriesTable c_obliquity_series_l10(int truncation) noexcept {
    switch (truncation) {
        case 0: return c_ObliquitySeriesTable{10, 0, c_obliquity_modes_l10_i0, c_obliquity_coeffs_l10_i0};
        case 2: return c_ObliquitySeriesTable{10, 2, c_obliquity_modes_l10_i2, c_obliquity_coeffs_l10_i2};
        case 4: return c_ObliquitySeriesTable{10, 4, c_obliquity_modes_l10_i4, c_obliquity_coeffs_l10_i4};
        default: return c_ObliquitySeriesTable{};
    }
}

// The half-angle table of the general truncation.
inline c_ObliquityGeneralTable c_obliquity_general_l10() noexcept {
    return c_ObliquityGeneralTable{10, c_obliquity_general_modes_l10, c_obliquity_general_terms_l10};
}
